INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/09/22 14:59:59", 126401, "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", 1, 10001, -470.0, 0.0, 2, "クローチェ", 1, "2023/06/30 12:00:00", 1, 2002, 1.47);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/09/22 14:59:59", 126401, "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", 1, 10002, -470.0, 0.0, 1, "クローチェ", 2, "2023/06/30 12:00:00", 2, 2002, 2.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/09/22 14:59:59", 126501, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 1, 10003, -470.0, 0.0, 2, "ライラエル", 2, "2023/06/30 12:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/09/22 14:59:59", 126501, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 1, 10004, -470.0, 0.0, 1, "ライラエル", 1, "2023/06/30 12:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/22 14:59:59", 127702, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2, 10005, -470.0, 0.0, 2, "リンド", 2, "2023/09/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/22 14:59:59", 127702, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2, 10006, -470.0, 0.0, 2, "リンド", 2, "2023/09/15 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/22 14:59:59", 127802, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 2, 10007, -470.0, 0.0, 1, "ヴルム", 1, "2023/09/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2023/12/22 14:59:59", 127802, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2, 10008, -470.0, 0.0, 1, "ヴルム", 2, "2023/09/15 15:00:00", 2, 2002, 6.5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/22 14:59:59", 129602, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 3, 10009, -470.0, 0.0, 1, "アネモネ", 2, "2023/12/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/22 14:59:59", 129602, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 3, 10010, -470.0, 0.0, 1, "アネモネ", 2, "2023/12/15 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/22 14:59:59", 129701, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 3, 10011, -470.0, 0.0, 1, "ネフィ=ネラ", 1, "2023/12/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/03/22 14:59:59", 129701, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 3, 10012, -470.0, 0.0, 1, "ネフィ=ネラ", 2, "2023/12/15 15:00:00", 2, 2002, 6.2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/22 14:59:59", 130301, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 4, 10013, -470.0, 0.0, 5, "カノン", 3, "2024/03/15 15:00:00", 1, 2002, 3.1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/22 14:59:59", 130301, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 4, 10014, -470.0, 0.0, 2, "カノン", 3, "2024/03/15 15:00:00", 2, 2002, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/22 14:59:59", 130401, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 4, 10015, -470.0, 0.0, 2, "ナーナ", 2, "2024/03/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/06/22 14:59:59", 130401, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 4, 10016, -470.0, 0.0, 1, "ナーナ", 2, "2024/03/15 15:00:00", 2, 2002, 3.35);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/22 14:59:59", 130502, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 5, 10017, -470.0, 0.0, 1, "ホウオウ", 1, "2024/06/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/22 14:59:59", 130502, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 5, 10018, -470.0, 0.0, 1, "ホウオウ", 2, "2024/06/15 15:00:00", 2, 2002, 3.18);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/22 14:59:59", 130503, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 5, 10019, -470.0, 0.0, 4, "ホウオウ", 4, "2024/06/15 15:00:00", 3, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/22 14:59:59", 123301, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 5, 10020, -470.0, 0.0, 2, "ネア", 1, "2024/06/15 15:00:00", 1, 2002, 4.9);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/09/22 14:59:59", 123301, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 5, 10021, -470.0, 0.0, 2, "ネア", 1, "2024/06/15 15:00:00", 2, 2002, 4.8);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/12/22 14:59:59", 133301, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 6, 10022, -470.0, 0.0, 1, "カリザ", 3, "2024/09/15 15:00:00", 1, 2002, 4.922);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/12/22 14:59:59", 133301, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 6, 10023, -470.0, 0.0, 5, "カリザ", 3, "2024/09/15 15:00:00", 2, 2002, 9.638);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/12/22 14:59:59", 133401, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 6, 10024, -470.0, 0.0, 2, "ミーア", 1, "2024/09/15 15:00:00", 1, 2002, 2.88);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2024/12/22 14:59:59", 133401, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 6, 10025, -470.0, 0.0, 1, "ミーア", 5, "2024/09/15 15:00:00", 2, 2002, 4.818);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/22 14:59:59", 133002, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 7, 10026, -470.0, 0.0, 1, "グレイス", 2, "2024/12/15 15:00:00", 1, 2002, 1.78);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/22 14:59:59", 133002, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 7, 10027, -470.0, 0.0, 7, "グレイス", 1, "2024/12/15 15:00:00", 2, 2002, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/22 14:59:59", 133102, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 7, 10028, -470.0, 0.0, 2, "ヴァイオレット", 6, "2024/12/15 15:00:00", 1, 2002, 4.28);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/03/22 14:59:59", 133102, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 7, 10029, -470.0, 0.0, 1, "ヴァイオレット", 1, "2024/12/15 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/23 14:59:59", 136902, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 8, 10030, -470.0, 0.0, 1, "ルルィ", 2, "2025/03/15 15:00:00", 1, 2002, 5.53);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/23 14:59:59", 136902, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 8, 10031, -470.0, 0.0, 7, "ルルィ", 9, "2025/03/15 15:00:00", 2, 2002, 6.05);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/23 14:59:59", 137001, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 8, 10032, -470.0, 0.0, 1, "デュラン", 2, "2025/03/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/06/23 14:59:59", 137001, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 8, 10033, -470.0, 0.0, 1, "デュラン", 2, "2025/03/15 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/23 14:59:59", 135902, "おう\n好きなもん持ってきな", 9, 10034, -470.0, 0.0, 2, "サツキ", 2, "2025/06/16 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/23 14:59:59", 135902, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 9, 10035, -470.0, 0.0, 6, "サツキ", 1, "2025/06/16 15:00:00", 2, 2002, 4.935);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/23 14:59:59", 135802, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 9, 10036, -470.0, 0.0, 5, "ユキノ", 2, "2025/06/16 15:00:00", 1, 2002, 7.441);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/09/23 14:59:59", 135802, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 9, 10037, -470.0, 0.0, 7, "ユキノ", 7, "2025/06/16 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/22 14:59:59", 130901, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 10, 10038, -470.0, 0.0, 2, "クルル", 2, "2025/09/16 15:00:00", 1, 2002, 2.295);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/22 14:59:59", 130901, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 10, 10039, -470.0, 0.0, 6, "クルル", 1, "2025/09/16 15:00:00", 2, 2002, 6.281);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/22 14:59:59", 137701, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 10, 10040, -470.0, 0.0, 1, "ヴォルガーノ", 2, "2025/09/16 15:00:00", 1, 2002, 5.549);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2025/12/22 14:59:59", 137701, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 10, 10041, -470.0, 0.0, 6, "ヴォルガーノ", 3, "2025/09/16 15:00:00", 2, 2002, 2.64);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/23 11:59:59", 132801, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 11, 10042, -470.0, 0.0, 4, "ライラエル", 7, "2025/12/15 15:00:00", 1, 2002, 7.642);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/23 11:59:59", 132802, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 11, 10043, -470.0, 0.0, 1, "ライラエル", 1, "2025/12/15 15:00:00", 2, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/23 11:59:59", 134502, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 11, 10044, -470.0, 0.0, 1, "クローチェ", 1, "2025/12/15 15:00:00", 1, 2002, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/03/23 11:59:59", 134501, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 11, 10045, -470.0, 0.0, 1, "クローチェ", 2, "2025/12/15 15:00:00", 2, 2002, 3.72);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/22 11:59:59", 138201, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 12, 10046, -470.0, 0.0, 1, "ネフィ＝ネラ", 2, "2026/03/16 12:00:00", 1, 2002, 4.991);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/22 11:59:59", 138201, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 12, 10047, -470.0, 0.0, 4, "ネフィ＝ネラ", 1, "2026/03/16 12:00:00", 2, 2002, 3.877);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/22 11:59:59", 136001, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 12, 10048, -470.0, 0.0, 6, "アラクネ", 4, "2026/03/16 12:00:00", 1, 2002, 1.71);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/06/22 11:59:59", 136001, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 12, 10049, -470.0, 0.0, 2, "アラクネ", 5, "2026/03/16 12:00:00", 2, 2002, 5.32);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/09/22 11:59:59", 135401, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 13, 10050, -470.0, 0.0, 4, "アネモネ", 9, "2026/06/15 12:00:00", 1, 2002, 3.727);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("2026/09/22 11:59:59", 135401, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 13, 10051, -470.0, 0.0, 9, "アネモネ", 7, "2026/06/15 12:00:00", 2, 2002, 7.213);
